import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.BxCN1dRw.js";const p=JSON.parse('{"title":"Walkthrough: Shared knowledge bases and permission inheritance","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/library-grants"},"headers":[],"relativePath":"en/tutorials/library-grants.md","filePath":"en/tutorials/library-grants.md"}'),r={name:"en/tutorials/library-grants.md"};function i(d,e,o,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="walkthrough-shared-knowledge-bases-and-permission-inheritance" tabindex="-1">Walkthrough: Shared knowledge bases and permission inheritance <a class="header-anchor" href="#walkthrough-shared-knowledge-bases-and-permission-inheritance" aria-label="Permalink to &quot;Walkthrough: Shared knowledge bases and permission inheritance&quot;">​</a></h1><p>Personal writing still means signing in, opening &quot;My documents&quot; from the sidebar and saving the first document. This chapter adds shared spaces: Owner/Admin create a shared knowledge base from the sidebar&#39;s &quot;Knowledge bases&quot;, rename it, and grant read-only or editable access to already-registered members.</p><p>Operation names on the knowledge base and grant pages stay consistent across Chinese and English:</p><table tabindex="0"><thead><tr><th>Page element</th><th>Chinese</th><th>English</th></tr></thead><tbody><tr><td>Business nav</td><td>知识库</td><td>Knowledge bases</td></tr><tr><td>Knowledge base name</td><td>知识库名称</td><td>Knowledge base name</td></tr><tr><td>Save name</td><td>保存库名</td><td>Save name</td></tr><tr><td>New action</td><td>新建文档</td><td>New document</td></tr><tr><td>Owning knowledge base</td><td>所在知识库</td><td>Open the knowledge base</td></tr><tr><td>Grants section</td><td>知识库授权</td><td>Knowledge base access</td></tr><tr><td>Member select</td><td>选择成员</td><td>Select member</td></tr><tr><td>Access select</td><td>访问权限</td><td>Access</td></tr><tr><td>Read-only</td><td>只读</td><td>Read-only</td></tr><tr><td>Editable</td><td>可编辑</td><td>Editable</td></tr><tr><td>Save grant</td><td>保存授权</td><td>Save grant</td></tr><tr><td>Revoke</td><td>撤销 {邮箱} 的授权</td><td>Revoke {email}’s access</td></tr><tr><td>Delete knowledge base</td><td>删除知识库</td><td>Delete knowledge base</td></tr></tbody></table><h2 id="_1-walking-through-it-with-two-accounts" tabindex="-1">1. Walking through it with two accounts <a class="header-anchor" href="#_1-walking-through-it-with-two-accounts" aria-label="Permalink to &quot;1. Walking through it with two accounts&quot;">​</a></h2><ol><li>Sign in as the Owner, open &quot;Knowledge bases&quot;, create &quot;团队手册&quot;. Click &quot;New document&quot; inside the knowledge base and save a Markdown document.</li><li>Register a colleague&#39;s account in another browser. At this point the colleague can neither read the document nor see the shared knowledge base.</li><li>The Owner clicks &quot;Open the knowledge base&quot; from the document, picks the colleague under &quot;Knowledge base access&quot;, and saves &quot;Read-only&quot;.</li><li>The colleague opens the shared knowledge base from the sidebar&#39;s &quot;Knowledge bases&quot;: searching and reading work; creating and editing do not.</li><li>The Owner changes the colleague to &quot;Editable&quot;. After refreshing, the colleague can create new documents or edit explicitly.</li><li>The Owner revokes the grant. The colleague&#39;s subsequent knowledge base queries, searches, reads and saves are all denied; refreshing shows the denial.</li></ol><p>The server decides role changes — no re-login needed. Already-open content is not wiped remotely; subsequent API requests run under the current grant, and the page picks up the new state when re-querying or regaining focus. This chapter introduces no real-time permission push.</p><h2 id="_2-who-can-do-what" tabindex="-1">2. Who can do what <a class="header-anchor" href="#_2-who-can-do-what" aria-label="Permalink to &quot;2. Who can do what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Qualification</th><th>Read/search in knowledge bases</th><th>Document writes</th><th>Create/rename/grant</th></tr></thead><tbody><tr><td>Owner / Admin</td><td>All knowledge bases</td><td>All knowledge bases</td><td>Allowed</td></tr><tr><td>Member + Reader</td><td>Granted knowledge bases</td><td>Denied</td><td>Denied</td></tr><tr><td>Member + Editor</td><td>Granted knowledge bases</td><td>Granted knowledge bases</td><td>Denied</td></tr><tr><td>Member, no Grant</td><td>Invisible</td><td>Invisible</td><td>Denied</td></tr></tbody></table><p>Personal knowledge bases use the same Grant; the first save prepares Editor automatically, and new features never publish personal knowledge bases to other ordinary users. Owner/Admin can still manage and read all personal knowledge bases under the confirmed model. Assigning a Reader grant to an administrator never reduces what the organization role already allows.</p><p>Library deletion and file cleanup arrive with the later deletion chapter; this chapter manages names, access scope and grants.</p><h2 id="_3-grants-decide-data-reads-and-writes" tabindex="-1">3. Grants decide data reads and writes <a class="header-anchor" href="#_3-grants-decide-data-reads-and-writes" aria-label="Permalink to &quot;3. Grants decide data reads and writes&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/crates/app/src/modules/knowledge/bases.rs" target="_blank" rel="noreferrer">knowledge base interface and use cases</a> provide the visible list, creation, detail and rename. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/crates/app/src/modules/knowledge/grants.rs" target="_blank" rel="noreferrer">Grant use cases</a> handle grant listing, granting and revoking. Granting and revoking commit in the same transaction as the Audit; repeated operations without an actual change do not append another grant event.</p><p>The document list API gains an optional <code>knowledge_base_id</code>; without it the scope is still the personal space. Creating a document can also target a knowledge base. The list returns summaries only, and title search still escapes <code>%</code>, <code>_</code> and backslash. Cursors bind to the account, the knowledge base scope, the filter and the ordering — changing knowledge bases forces a fresh query.</p><p>Invisible documents or knowledge bases return 404; readable but not writable returns 403. Read / List / Search / Create / Update all verify on the backend — hidden buttons, direct URLs or reused cursors cannot bypass them.</p><p>The <code>can_edit / can_manage / can_create</code> in each response is the server&#39;s current judgment. The personal document list also returns the current <code>can_create</code>: allowed for a first write without a personal knowledge base, denied after revocation so re-initialization cannot sneak past. The frontend uses these flags only to improve the experience; executing a mutation still re-validates. GrantAccess and the related SDK types are generated from the Rust contract — the frontend maintains no parallel role-derivation rules.</p><h2 id="_4-how-revocation-orders-with-an-in-flight-save" tabindex="-1">4. How revocation orders with an in-flight save <a class="header-anchor" href="#_4-how-revocation-orders-with-an-in-flight-save" aria-label="Permalink to &quot;4. How revocation orders with an in-flight save&quot;">​</a></h2><p>An ordinary document write first takes the current Membership&#39;s shared lock, then the Knowledge Base&#39;s shared lock, checks the permission and saves. A grant change locks both the operator and the target member through Organization&#39;s <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer">ordered member-lock interface</a>, then takes the knowledge base&#39;s exclusive lock.</p><p>If a save already holds the knowledge base lock, the revocation waits for that save to complete before committing; requests starting after the revocation commits cannot keep writing. Conversely, when the revocation takes the lock first, later saves read &quot;no grant&quot; and are denied. Grant caches or idempotent results cannot skip this step.</p><p>With multiple members involved, locks are taken in member-ID order, matching organization member management; new attachment or job authorization must respect the same commit order. Core never reads Knowledge tables — the reference business collaborates through Core&#39;s public interfaces.</p><h2 id="_5-pages-and-caching" tabindex="-1">5. Pages and caching <a class="header-anchor" href="#_5-pages-and-caching" aria-label="Permalink to &quot;5. Pages and caching&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/packages/views/src/knowledge/knowledge-bases-view.tsx" target="_blank" rel="noreferrer">Knowledge Views</a> reuse Core&#39;s member directory to pick registered users — no invitation step. Documents in the personal space and inside a knowledge base share the same <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/packages/views/src/knowledge/documents-view.tsx" target="_blank" rel="noreferrer">list/edit View</a>; the knowledge base scope enters the Query key and the API parameters, and unsaved drafts stay separate per account and knowledge base.</p><p>Grant control names resolve with the UI language, and the revoke button&#39;s accessible name carries the target email (&quot;撤销 {邮箱} 的授权&quot; / &quot;Revoke {email}’s access&quot;) so screen readers identify the target in both languages; bilingual View tests cover the representative pages.</p><p>Readers see the read-only page, and even opening the edit URL directly leaves the save controls disabled. After a 403/404 on save, resubmitting is disabled immediately and permissions are re-read while the unsaved text stays untouched; only an explicit &quot;re-check permissions&quot; confirmed by the server restores saving. A failed permission re-read never lets the stale UI permission submit. All saved resources remain Query-managed — nothing is copied into a second business store.</p><p>Knowledge bases, grants and member lists default to 50 per page, capped at 100. The page offers &quot;Load more&quot; and failed-read retries, and the browser keeps at most ten pages per list to avoid unbounded growth. The backend never returns every knowledge base to ordinary users for frontend filtering.</p><h2 id="_6-verifying-from-the-public-entry" tabindex="-1">6. Verifying from the public entry <a class="header-anchor" href="#_6-verifying-from-the-public-entry" aria-label="Permalink to &quot;6. Verifying from the public entry&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knowledge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge-bases.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge-bilingual.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Real PostgreSQL tests cover the role/Grant matrix, invisible search, rename, scope binding, grant-audit rollback and revocation/write lock races. View tests verify creating a shared knowledge base → saving inside it, granting/revoking, renaming, and the Reader&#39;s page and direct edit entry.</p><p>Run once when the key flow completes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/knowledge-grants.spec.ts</span></span></code></pre></div><p>Two real browsers walk invisible → Reader → Editor → revoked, exercising the pages together with Cookies, the generated SDK, server authorization and the actual database.</p><p>This chapter only extends the knowledge reference business; the knowledge base model, API, Views, contract symbols, tests and tutorial are registered in the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">ownership manifest</a>. Core&#39;s ordered member locks and member directory remain. Later attachments reuse the same knowledge-base-level grant boundary — no per-file ACL.</p><hr><p>Source version：<code>1983c7865d35</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/docs/tutorials/07-library-grants.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,34)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
